function eventosDeGoogle(resp) {
  // La API devuelve un solo item con la lista en "items". Si la peticion falla,
  // el nodo HTTP deja pasar el error como dato y aqui se convierte en motivo:
  // "no he podido leer" no es lo mismo que "no hay nada", y confundirlos es
  // justo el fallo del que no te enteras.
  if (!resp || resp.error || !Array.isArray(resp.items)) {
    const e = resp?.error;
    const motivo = String(e?.message ?? e?.description ?? e ?? 'Google no ha devuelto eventos');
    return { error: motivo.slice(0, 200), eventos: [] };
  }
  const eventos = [];
  for (const ev of resp.items) {
    if (ev.status === 'cancelled') continue;
    // Una invitacion que rechazaste sigue en tu calendario, pero no vas.
    const yo = (ev.attendees ?? []).find((a) => a.self);
    if (yo && yo.responseStatus === 'declined') continue;
    const todoElDia = !ev.start?.dateTime;
    const d = todoElDia
      ? DateTime.fromISO(String(ev.start?.date ?? ''), { zone: 'Europe/Madrid' })
      : DateTime.fromISO(ev.start.dateTime).setZone('Europe/Madrid');
    if (!d.isValid) continue;
    eventos.push({
      id: ev.id,
      titulo: String(ev.summary ?? '').trim() || '(sin título)',
      descripcion: String(ev.description ?? ''),
      d,
      todoElDia,
    });
  }
  eventos.sort((a, b) => a.d.toMillis() - b.d.toMillis());
  return { error: null, eventos };
}

// Modo: Run Once for All Items.
// Herramienta "agenda" del agente. Lee tu Google Calendar y devuelve los
// eventos en una ventana alrededor de hoy, ya ordenados y en texto: al modelo le
// sale mejor leer una lista de frases que un JSON con fechas ISO.
//
// Solo van el titulo y la hora, nunca la descripcion. Cualquiera puede meterte
// un evento en el calendario mandandote una invitacion, y lo que escriba ahi
// llegaria al modelo como si lo hubieras apuntado tu.

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

const ahora = DateTime.now().setZone('Europe/Madrid');
// Una semana hacia atras para poder contestar "¿no era ayer lo del dentista?",
// y dos meses hacia delante, que es hasta donde llega una agenda personal. La
// peticion de "Leer el calendario" usa la misma ventana: si cambias una,
// cambia la otra.
const desde = ahora.minus({ days: 7 });
const hasta = ahora.plus({ days: 60 });

// La franja va escrita para que el modelo no tenga que deducirla de la hora.
// Ante "¿tengo algo el 24 por la tarde?" un modelo pequeño cruza mejor una
// etiqueta que un 14:30. Los cortes casan con las horas por defecto del
// clasificador: mañana 09:00, tarde 17:00, noche 21:00.
function franja(d) {
  if (d.hour < 14) return 'mañana';
  if (d.hour < 21) return 'tarde';
  return 'noche';
}

const cabecera = 'Hoy es ' + DIAS[ahora.weekday - 1] + ' ' +
  ahora.toFormat('dd/LL/yyyy') + ' y son las ' + ahora.toFormat('HH:mm') + '.';

const { error, eventos } = eventosDeGoogle($input.first()?.json);

if (error) {
  return [{ json: { response: cabecera + '\nNo he podido leer el calendario de Google (' +
    error + '). No sé qué hay apuntado: dilo así, y no des ningún día por libre.' } }];
}

const lineas = eventos.map((e) => {
  const dia = DIAS[e.d.weekday - 1] + ' ' + e.d.day + ' de ' +
    MESES[e.d.month - 1] + ' de ' + e.d.year;
  const cuando = e.todoElDia
    ? dia + ', todo el día'
    : dia + ' a las ' + e.d.toFormat('HH:mm') + ', por la ' + franja(e.d);
  const paso = e.todoElDia ? e.d.endOf('day') < ahora : e.d < ahora;
  return '- ' + cuando + (paso ? ' (ya pasó)' : '') + ': ' + e.titulo;
});

const respuesta = lineas.length
  ? cabecera + '\nEventos del calendario entre el ' + desde.toFormat('dd/LL') +
    ' y el ' + hasta.toFormat('dd/LL') + ':\n' + lineas.join('\n')
  : cabecera + '\nNo hay ningún evento en el calendario entre el ' +
    desde.toFormat('dd/LL') + ' y el ' + hasta.toFormat('dd/LL') + '.';

return [{ json: { response: respuesta } }];
